// Generated by @nx-devkit/sverka — edit freely.
//
// Every step becomes an Nx target with its own inputs, outputs and cache:
//   nx run <project>:<pipeline>:<step>

import {
  Project,
  Pipeline,
  ShellStep,
  Entry,
  push,
  manual,
} from '@sverka/workflow'

const proj = new Project("gh-debt")

const ci = new Pipeline(proj, "ci")

new ShellStep(ci, "typecheck", { command: "npm run typecheck" })
new ShellStep(ci, "test", { command: "npm run test" })
new ShellStep(ci, "build", { command: "npm run build" })

export const onPush = new Entry(ci, "on-push", {
  trigger: push(),
  roots: ["typecheck", "test", "build"],
})

// ── One-time repository provisioning ─────────────────────────────
// Everything in this pipeline is applied once, by hand, with an operator
// token — it is the setup a repository needs before a gate means anything.
//
// It is a separate pipeline so that re-running the gate never depends on this
// having been run, but it is *not* separate from verification: `repo-health`
// carries `bootstrap-drift`, which re-checks every invariant here on every run.
// Without that step, "applied once" silently becomes "never checked" — the
// split would create a blind spot instead of removing one.
//
// These steps call the API and write no files, so they need no checkout.
const bootstrap = new Pipeline(proj, "bootstrap", {
  permissions: {
    administration: "write",
    metadata: "write",
    "security-events": "write",
    contents: "read",
  },
  bootstrap: "none",
})

// Require the CI check on the default branch, so a green `main` is enforced
// rather than observed. `PUT` is idempotent: re-running sets the same rule.
// The context must match the workflow's job `name` — rename the job in
// `.github/workflows/ci.yml` and this goes stale.
new ShellStep(bootstrap, "protect-main", {
  command: "branch=$(gh repo view --json defaultBranchRef --jq '.defaultBranchRef.name') || { echo \"cannot resolve the default branch\"; exit 1; }; body='{\"required_status_checks\":{\"strict\":true,\"contexts\":[\"Typecheck, build, test\"]},\"enforce_admins\":false,\"required_pull_request_reviews\":{\"dismiss_stale_reviews\":true,\"require_code_owner_reviews\":false},\"restrictions\":null}'; printf '%s' \"$body\" | gh api --method PUT \"repos/{owner}/{repo}/branches/$branch/protection\" --input - || { echo \"could not set protection on $branch — the token needs administration:write\"; exit 1; }; echo \"required status checks set on $branch\"",
  runtime: { shell: "sh" },
})

// Secret scanning with push protection, Dependabot security updates and
// automated security fixes. Both calls are idempotent.
new ShellStep(bootstrap, "security-features", {
  command: "printf '%s' '{\"security_and_analysis\":{\"secret_scanning\":{\"status\":\"enabled\"},\"secret_scanning_push_protection\":{\"status\":\"enabled\"},\"dependabot_security_updates\":{\"status\":\"enabled\"}}}' | gh api --method PATCH repos/{owner}/{repo} --input - || { echo \"could not enable security features — the token needs administration:write\"; exit 1; }; printf '' | gh api --method PUT repos/{owner}/{repo}/automated-security-fixes --input - || { echo \"could not enable automated security fixes\"; exit 1; }; echo \"security features enabled\"",
  runtime: { shell: "sh" },
})

// Enable GitHub's default (managed) CodeQL code scanning, but only when no
// code scanning is already configured — never overwrite a custom CodeQL
// workflow or an already-configured default setup. Idempotent.
new ShellStep(bootstrap, "enable-code-scanning", {
  command: "state=$(gh api repos/{owner}/{repo}/code-scanning/default-setup --jq '.state' 2>/dev/null); if [ \"$state\" = \"configured\" ]; then echo \"code scanning already configured (default setup)\"; elif gh api repos/{owner}/{repo}/contents/.github/workflows/codeql.yml >/dev/null 2>&1 || gh api repos/{owner}/{repo}/contents/.github/workflows/codeql-analysis.yml >/dev/null 2>&1; then echo \"custom CodeQL workflow present — skipping default setup\"; else printf '{\"state\":\"configured\"}' | gh api --method PATCH repos/{owner}/{repo}/code-scanning/default-setup --input - || { echo \"could not enable code scanning — the token needs administration:write\"; exit 1; }; echo \"code scanning enabled (default setup)\"; fi",
  runtime: { shell: "sh" },
})


export const bootstrapApply = new Entry(bootstrap, "apply", {
  trigger: manual(),
  roots: ["protect-main", "security-features", "enable-code-scanning"],
})

// ── GitHub-side repository health ──────────────────────────────────
// These check the state of the repository on GitHub, not the code.
const repoHealth = new Pipeline(proj, "repo-health", {
  permissions: {
    contents: "read",
    "pull-requests": "read",
    checks: "read",
    "security-events": "read",
    actions: "read",
  },
  inputs: {
    GITHUB_TOKEN: { type: "string", secret: true, default: "" },
    // Optional: a token with the vulnerability-alerts permission —
    // the workflow token cannot read the Dependabot alerts.
    REPO_HEALTH_TOKEN: { type: "string", secret: true, default: "" },
  },
  bootstrap: "checkout",
})

// Every GitHub Actions check-run on the default branch is green (non-Actions apps are reported, never gated).
// Only the latest run of each check name is judged, and only once it completed: the check-runs API returns
// every run on the commit — superseded re-runs and in-progress jobs included — while GitHub's UI shows the
// latest, so judging all of them keeps the gate red on a commit whose newest run is green. This pipeline's
// own run on the branch it gates is the in-progress case.
// The grouping must span pages: `gh api --paginate` applies `--jq` to each page separately, which would
// group a superseded failure apart from its successful retry, so the runs are slurped into one array here.
new ShellStep(repoHealth, "main-green", {
  command: "branch=$(gh repo view --json defaultBranchRef --jq '.defaultBranchRef.name') || exit 1; raw=$(gh api --paginate \"repos/{owner}/{repo}/commits/$branch/check-runs\") || { echo \"check-runs query failed\"; exit 1; }; out=$(printf '%s\n' \"$raw\" | jq -s -r '[.[] | .check_runs[]] | group_by([.app.slug, .name]) | map(sort_by(.id) | last) | map(select(.app.slug == \"github-actions\")) | map(select(.status == \"completed\")) | map(select(.conclusion != \"success\" and .conclusion != \"skipped\" and .conclusion != \"neutral\")) | .[] | \"\\(.name) (\\(.conclusion // .status))\"') || { echo \"check-runs filter failed\"; exit 1; }; [ -z \"$out\" ] || { echo \"non-green checks on $branch:\"; echo \"$out\"; exit 1; }; other=$(printf '%s\n' \"$raw\" | jq -s -r '[.[] | .check_runs[]] | group_by([.app.slug, .name]) | map(sort_by(.id) | last) | map(select(.app.slug != \"github-actions\")) | .[] | \"\\(.app.slug): \\(.name) (\\(.conclusion // .status))\"') || { echo \"check-runs filter failed\"; exit 1; }; [ -z \"$other\" ] || { echo \"checks from other apps on $branch (reported, never gated):\"; echo \"$other\"; }",
  runtime: { shell: "sh" },
})

// No unresolved review threads in the last 20 merged PRs (GraphQL).
// GraphQL cannot order by merge time, so a window of 100 is fetched by creation time and the 20 most
// recently *merged* are selected client-side. A window that is itself truncated is reported, so a
// missed PR fails the check rather than passing it silently.
new ShellStep(repoHealth, "review-debt", {
  command: "count=$(gh api graphql -f query='query($owner:String!,$name:String!){repository(owner:$owner,name:$name){pullRequests(first:100,states:MERGED,orderBy:{field:CREATED_AT,direction:DESC}){pageInfo{hasNextPage}nodes{mergedAt reviewThreads(first:100){pageInfo{hasNextPage}nodes{isResolved}}}}}}' -F owner='{owner}' -F name='{repo}' --jq '.data.repository.pullRequests as $prs | ($prs.nodes | sort_by(.mergedAt) | reverse | .[0:20]) as $recent | ([ $recent[].reviewThreads.nodes[] | select(.isResolved==false) ] | length) as $threads | ([ $recent[].reviewThreads.pageInfo.hasNextPage | select(.) ] | length) as $truncated | $threads + $truncated + (if $prs.pageInfo.hasNextPage then 1 else 0 end)') || exit 1; [ \"$count\" = \"0\" ] || { echo \"unresolved threads or truncated thread pages: $count\"; exit 1; }",
  runtime: { shell: "sh" },
})

// No open Dependabot alerts (advanced security).
new ShellStep(repoHealth, "dependabot-alerts", {
  command: "[ -z \"$REPO_HEALTH_TOKEN\" ] || export GH_TOKEN=\"$REPO_HEALTH_TOKEN\"; out=$(gh api --paginate 'repos/{owner}/{repo}/dependabot/alerts?state=open' --jq '.[].number' 2>&1) || { if echo \"$out\" | grep -qi \"not accessible\\|403\\|404\"; then if [ -n \"$REPO_HEALTH_TOKEN\" ]; then echo \"REPO_HEALTH_TOKEN cannot read dependabot alerts — check its scopes (vulnerability-alerts read) or remove the secret\"; exit 1; fi; echo \"::warning::GITHUB_TOKEN cannot read dependabot alerts (needs the vulnerability-alerts permission); check skipped\"; exit 0; fi; echo \"$out\"; exit 1; }; [ -z \"$out\" ] || { echo \"open dependabot alerts:\"; echo \"$out\"; exit 1; }",
  runtime: { shell: "sh", secrets: ["REPO_HEALTH_TOKEN"] },
})

// No open code-scanning alerts (advanced security).
new ShellStep(repoHealth, "code-scanning", {
  command: "out=$(gh api --paginate 'repos/{owner}/{repo}/code-scanning/alerts?state=open' --jq '.[].number' 2>&1) || { if echo \"$out\" | grep -qi \"not found\\|404\\|403\\|not accessible\"; then echo \"::warning::code scanning is not available for this repository — check skipped\"; exit 0; fi; echo \"$out\"; exit 1; }; [ -z \"$out\" ] || { echo \"open code scanning alerts:\"; echo \"$out\"; exit 1; }",
  runtime: { shell: "sh" },
})

// No open secret-scanning alerts (advanced security).
new ShellStep(repoHealth, "secret-scanning", {
  command: "out=$(gh api --paginate 'repos/{owner}/{repo}/secret-scanning/alerts?state=open' --jq '.[].number' 2>&1) || { if echo \"$out\" | grep -qi \"not found\\|404\\|403\\|not accessible\"; then echo \"::warning::secret scanning is not available for this repository — check skipped\"; exit 0; fi; echo \"$out\"; exit 1; }; [ -z \"$out\" ] || { echo \"open secret scanning alerts:\"; echo \"$out\"; exit 1; }",
  runtime: { shell: "sh" },
})

// No remote branch left behind by a merged PR.
new ShellStep(repoHealth, "stale-branches", {
  command: "remote=$(git ls-remote --heads origin 2>&1) || { echo \"ls-remote failed: $remote\"; exit 1; }; branches=$(printf '%s\n' \"$remote\" | sed 's|.*refs/heads/||') owner=$(gh repo view --json owner --jq '.owner.login') || exit 1; branch=$(gh repo view --json defaultBranchRef --jq '.defaultBranchRef.name') || exit 1; stale=\"\"; for b in $branches; do [ \"$b\" = \"$branch\" ] && continue; n=$(gh pr list --head \"$b\" --state merged --json number,headRepositoryOwner --jq '[.[] | select(.headRepositoryOwner.login == \"'\"$owner\"'\")] | length') || exit 1; [ \"$n\" -gt 0 ] && stale=\"$stale $b\"; done; [ -z \"$stale\" ] || { echo \"stale branches:$stale\"; exit 1; }",
  runtime: { shell: "sh" },
})

// Lists the open PRs (informational, never fails).
new ShellStep(repoHealth, "open-prs", {
  command: "gh pr list --state open --limit 100 --json number,title,author --jq '.[] | \"#\\(.number) \\(.title) (@\\(.author.login))\"' || true",
  runtime: { shell: "sh" },
})

// The invariants the bootstrap pipeline applies, re-checked here on every run.
// A failed query is drift, not a pass: a check that cannot be read is not green.
// When this fails, run `bootstrap:apply`.
new ShellStep(repoHealth, "bootstrap-drift", {
  command: "fail=\"\"; branch=$(gh repo view --json defaultBranchRef --jq '.defaultBranchRef.name') || { echo \"cannot resolve the default branch\"; exit 1; }; gh api \"repos/{owner}/{repo}/branches/$branch\" --jq '.protected' 2>/dev/null | grep -qx true || fail=\"$fail main-unprotected\"; gh api repos/{owner}/{repo} --jq '.security_and_analysis.secret_scanning.status' 2>/dev/null | grep -qx enabled || fail=\"$fail secret-scanning-off\"; gh api repos/{owner}/{repo} --jq '.security_and_analysis.secret_scanning_push_protection.status' 2>/dev/null | grep -qx enabled || fail=\"$fail push-protection-off\"; gh api repos/{owner}/{repo}/automated-security-fixes --jq '.enabled' 2>/dev/null | grep -qx true || fail=\"$fail automated-fixes-off\"; gh api repos/{owner}/{repo}/contents/SECURITY.md --jq '.name' >/dev/null 2>&1 || fail=\"$fail no-SECURITY.md\"; gh api repos/{owner}/{repo}/contents/.github/dependabot.yml --jq '.name' >/dev/null 2>&1 || fail=\"$fail no-dependabot.yml\"; cs_state=$(gh api repos/{owner}/{repo}/code-scanning/default-setup --jq '.state' 2>/dev/null); if [ \"$cs_state\" = \"configured\" ]; then :; elif gh api repos/{owner}/{repo}/contents/.github/workflows/codeql.yml >/dev/null 2>&1 || gh api repos/{owner}/{repo}/contents/.github/workflows/codeql-analysis.yml >/dev/null 2>&1; then :; else fail=\"$fail code-scanning-off\"; fi; [ -z \"$fail\" ] || { echo \"repository setup drift — run bootstrap:apply:$fail\"; exit 1; }; echo \"repository setup verified\"",
  runtime: { shell: "sh" },
})

export const repoHealthCheck = new Entry(repoHealth, "check", {
  trigger: manual(),
  roots: ["main-green", "bootstrap-drift", "review-debt", "dependabot-alerts", "code-scanning", "secret-scanning", "stale-branches", "open-prs"],
})

export default proj
